using System.Text;using System.Text.Json;namespace Test;public static class Program{    private static CliStatus status;    private static Company? company;    private static JsonSerializerOptions jsonSerializerOptions = new JsonSerializerOptions { IncludeFields = true };    private enum CliStatus    {        Init,        Loaded,        Exit    }    public static void Main(string[] args)    {        status = CliStatus.Init;        do        {            switch (status)            {                case CliStatus.Init:                    init();                    break;                case CliStatus.Loaded:                    menu();                    break;            }        } while (status != CliStatus.Exit);    }    private static void menu()    {        bool success = false;        do        {            Console.WriteLine("""                          菜单：                          q):退出                          1):添加一个职工                          2):列举所有职工                          3):删除职工                          4):修改职工信息                          5):查找职工                          6):排序                          7):清空当前Company的内容                          8):将当前company保存到company.json                          """);            var option = Console.ReadKey().KeyChar;            Console.WriteLine("");            switch (option)            {                case 'q':                    status = CliStatus.Exit;                    success = true;                    break;                case '1':                    success = company!.TryAddStaff();                    break;                case '2':                    Console.WriteLine(company!.GetStaffs());                    success = true;                    break;                case '3':                    success = company!.TryRemoveStaff();                    break;                case '4':                    success = company!.TryModifyStaff();                    break;                case '5':                    success = company!.TrySearchStaff();                    break;                case '6':                    // 很明显已经是屎山了                    Console.WriteLine("是否要按id降序排序，是输入yes，否则视为不是");                    if (Console.ReadLine() == "yes")                        company!.Order(true);                    else                        company!.Order(false);                    success = true;                    break;                case '7':                    Console.WriteLine("确定操作请输入yes");                    if (Console.ReadLine() == "yes")                    {                        company = new Company();                    }                    else                    {                        Console.WriteLine("操作取消");                    }                    success = true;                    break;                case '8':                    var content = JsonSerializer.Serialize(company, jsonSerializerOptions);                    using (StreamWriter writer = new StreamWriter("company.json", false, Encoding.UTF8))                    {                        writer.Write(content);                    }                    success = true;                    break;                default:                    Console.WriteLine("选择无效，请重新选择");                    break;            }            if (!success)                Console.WriteLine("操作失败");        } while (!success);    }    private static void init()    {        bool success = false;        Console.WriteLine("""                          选择一个初始化的方法：                          1):从company.json读取                          2):创建一个新Company对象                          """);        do        {            var option = Console.ReadKey().KeyChar;            switch (option)            {                case '1':                    success = loadFromFile();                    break;                case '2':                    company = new Company();                    success = true;                    break;                default:                    Console.WriteLine("");                    Console.WriteLine("选择无效，请重新选择");                    break;            }        } while (!success);        status = CliStatus.Loaded;    }    private static bool loadFromFile()    {        if (!File.Exists("company.json"))        {            Console.WriteLine("");            Console.WriteLine("未找到company.json");            return false;        }        try        {            using var fs = new FileStream("company.json", FileMode.Open);            company = JsonSerializer.Deserialize&lt;Company&gt;(fs);        }        // catch (FileNotFoundException)        // {        //     Console.WriteLine("未找到company.json");        //     return false;        // }        catch (JsonException)        {            Console.WriteLine("company.json的数据无效");            return false;        }        return true;    }}




