using System.Text;using System.Text.Json.Serialization;namespace Test;internal class Company{    // 暂时先用List&lt;T&gt;吧    // private List&lt;Department&gt; departments = new();    [JsonInclude]    private List&lt;Staff&gt; staffs = new();    public string GetStaffs()    {        StringBuilder sb = new StringBuilder();        foreach (var staff in staffs)        {            sb.Append(staff);            sb.Append(Environment.NewLine);        }        return sb.ToString();    }    public void AddStaff(Staff staff)    {        if (staffs.Contains(staff))            throw new ArgumentException($"The {staff.Name} had already been added.");        // if (!departments.Contains(staff.Department!))        //     throw new ArgumentException(        //         $"The {staff.Name} in {staff.Department}, whose department not in this company currently.");        // if (staff.Department is not null)        //     if (!departments.Contains(staff.Department))        //         departments.Add(staff.Department);        if (staffs.Find(s =&gt; s.Id == staff.Id) is not null)            throw new ArgumentException($"The {staff.Name} have a duplicate ID.");        staffs.Add(staff);    }    // public void RemoveStaff(Staff staff)    // {    //     if (!staffs.Contains(staff))    //         throw new ArgumentException($"The {staff.Name} had already been added.");    //     staffs.Remove(staff);    // }    public void RemoveStaff(int staffId)    {        var staff = staffs.Find(staff =&gt; staff.Id == staffId) ?? throw new ArgumentException($"Couldn't find a staff has ID {staffId}");        staffs.Remove(staff);    }    public Staff? SearchStaff(int staffId)    {        return staffs.Find(staff =&gt; staff.Id == staffId);    }    // public Staff? SearchStaff(string staffName)    // {    //     return staffs.Find(staff =&gt; staff.Name == staffName);    // }    public void Order(bool descending)    {        if (descending)        {            staffs.Sort((x, y) =&gt; y.Id.CompareTo(x.Id));        }        else        {            staffs.Sort((x, y) =&gt; x.Id.CompareTo(y.Id));        }    }}




