namespace Test;internal static class CompanyExtension{    internal static bool TryAddStaff(this Company company)    {        bool inputValid = false;        Console.WriteLine("""                          输入职工信息，以空格分隔                          姓名 编号 职工类型 部门                          """);        do        {            var input = (Console.ReadLine() ?? string.Empty).Split(' ');            if (input.Length == 4)            {                string name = input[0];                bool idParse = int.TryParse(input[1], out var id);                bool staffTypeParse = Enum.TryParse(typeof(StaffType), input[2], out var staffType);                string department = input[3];                if (idParse &amp;&amp; staffTypeParse)                {                    StaffType staffsType = (StaffType)staffType!;                    var staff = new Staff(name, id, staffsType, department);                    // 梅开二度屎山                    try                    {                        company.AddStaff(staff);                    }                    catch (ArgumentException)                    {                        return false;                    }                    inputValid = true;                }            }            if (!inputValid)                Console.WriteLine("输入无效，请重新输入");        } while (!inputValid);        return true;    }    internal static bool TryRemoveStaff(this Company company)    {        bool inputValid = false;        Console.WriteLine("输入要删除的职工id");        do        {            var input = Console.ReadLine() ?? string.Empty;            if (int.TryParse(input, out var id))            {                inputValid = true;                if (company.SearchStaff(id) is null)                {                    Console.WriteLine("不存在指定的职工");                    return false;                }                company.RemoveStaff(id);            }            if (!inputValid)                Console.WriteLine("输入无效，请重新输入");        } while (!inputValid);        return true;    }    internal static bool TryModifyStaff(this Company company)    {        bool inputValid = false;        bool inputInfoVaild = false;        Console.WriteLine("输入要修改的职工个人信息的id");        do        {            var input = (Console.ReadLine() ?? string.Empty);            if (int.TryParse(input, out var id))            {                inputValid = true;                var staff = company.SearchStaff(id);                if (staff is null)                {                    Console.WriteLine("不存在指定的职工");                    return false;                }                Console.WriteLine("""                                  输入职工信息，以空格分隔                                  姓名 职工类型 部门                                  """);                do                {                    var info = (Console.ReadLine() ?? string.Empty).Split(' ');                    if (info.Length == 3)                    {                        string name = info[0];                        bool staffTypeParse = Enum.TryParse(typeof(StaffType), info[1], out var staffType);                        StaffType staffsType = (StaffType)staffType!;                        string department = info[2];                        if (staffTypeParse)                        {                            staff.Name = name;                            staff.Type = staffsType;                            staff.Department = department;                            inputInfoVaild = true;                        }                    }                    if (!inputInfoVaild)                        Console.WriteLine("输入的信息无效，请重新输入");                } while (!inputInfoVaild);            }            if (!inputValid)                Console.WriteLine("输入无效，请重新输入");        } while (!inputValid);        return true;    }    internal static bool TrySearchStaff(this Company company)    {        bool inputValid = false;        Console.WriteLine("输入要搜索的职工个人信息的id");        do        {            var input = (Console.ReadLine() ?? string.Empty);            if (int.TryParse(input, out var id))            {                inputValid = true;                var staff = company.SearchStaff(id);                if (staff is null)                {                    Console.WriteLine("不存在指定的职工");                    return false;                }                Console.WriteLine(staff);            }            if (!inputValid)                Console.WriteLine("输入无效，请重新输入");        } while (!inputValid);        return true;    }}




