namespace Test;internal enum StaffType{    Empolyee,    Boss,    Manager}// 这里的Staff存在一个问题是ID是有符号的，不过负ID显得您身份特殊吗！internal class Staff{    public string Name { get; set; }    public int Id { get; init; }    public StaffType Type { get; set; }    public string Department { get; set; }    public Staff(string name, int id, StaffType type, string department)    {        (Name, Id, Type, Department) = (name, id, type, department);    }    // public Staff(string name, int id, Department department) : this(name, id, StaffType.Empolyee, department) { }    // public Staff(string name, int id) : this(name, id, StaffType.Empolyee, null) { }    public override string ToString()    {        return $"Staff(ID: {Id}, Name: {Name}, Type: {Type}, Department: {Department})";    }}



